contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // admin is the deployer (this test contract), recorded in the constructor
        vm.prank(address(this));
        bool ok = c.setOwner(newOwner);
        // Reference: setOwner always returns true once access control passes.
        // Mutant: returns false whenever newOwner == address(0).
        assertTrue(ok);
